 .agenda-panel { min-height: 300px; }
 .agenda-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; padding-bottom: 1.2rem; border-bottom: 1px solid var(--line); }
 .agenda-toolbar h2 { margin: .2rem 0 0; font: 700 1.5rem 'Playfair Display', serif; text-transform: capitalize; }
 .toolbar-label { color: var(--muted); font-size: .8rem; font-weight: 700; }
